"use client";
import { useMemo, useState } from "react";
import { universities } from "./data";
const nav=["Направления","Методика аудита","База вузов","Кейсы","Стоимость"];
const Pill=({children,kind="base"}:{children:React.ReactNode;kind?:"base"|"good"|"warm"})=><span className={`inline-flex rounded-full px-3 py-1 text-[10px] font-bold tracking-[.09em] uppercase ${kind==="good"?"bg-pistachio":kind==="warm"?"bg-terracotta":"border line"}`}>{children}</span>;
export default function Page(){const [country,setCountry]=useState<"AT"|"HU">("AT"),[query,setQuery]=useState("");const [sent,setSent]=useState(false);const filtered=useMemo(()=>universities.filter(x=>x.country===country&&`${x.name} ${x.city} ${x.specialty}`.toLowerCase().includes(query.toLowerCase())),[country,query]);return <main className="overflow-hidden">
  <header className="mx-auto flex max-w-[1400px] items-center justify-between px-5 py-5 lg:px-10"><a href="#top" className="font-display text-[25px] tracking-[-.06em]">Nexora <i className="not-italic text-[#b6654e]">Admissions</i></a><nav className="desktop flex gap-7 text-[12px] font-bold tracking-wide">{nav.map(x=><a key={x} href={`#${x.toLowerCase().replaceAll(" ","-")}`} className="transition hover:text-[#b6654e]">{x}</a>)}</nav><a href="#diagnostic" className="rounded-full bg-espresso px-4 py-3 text-[11px] font-bold text-white transition hover:bg-taupe">Записаться на диагностику <span className="ml-2 text-pistachio">↗</span></a></header>
  <section id="top" className="grid-bg relative border-y line"><div className="mx-auto grid min-h-[660px] max-w-[1400px] grid-cols-1 items-end lg:grid-cols-[1.1fr_.9fr]"><div className="px-5 py-18 lg:px-10 lg:py-28"><div className="reveal"><Pill kind="good">Приём 2026/2027 открыт</Pill></div><h1 className="reveal delay mt-7 max-w-4xl font-display text-[clamp(3.1rem,6.2vw,6.5rem)] leading-[.91] tracking-[-.07em]">Поступление в университеты <em className="font-normal text-[#b6654e]">Австрии и Венгрии</em> с гарантией соответствия требованиям.</h1><p className="reveal delay-2 mt-7 max-w-xl text-[15px] leading-7 text-taupe">Строгий академический аудит, проверка дедлайнов и полное сопровождение «под ключ» от экспертов.</p><div className="reveal delay-2 mt-9 flex flex-wrap gap-3"><a href="#database" className="rounded-full bg-espresso px-5 py-4 text-[12px] font-bold text-white">Подобрать программу <span className="ml-3 text-pistachio">↘</span></a><a href="#pricing" className="rounded-full border line px-5 py-4 text-[12px] font-bold">Узнать стоимость сопровождения <span className="ml-3">↘</span></a></div></div><div className="relative hidden min-h-[660px] border-l line lg:block"><div className="absolute right-[8%] top-[12%] h-[470px] w-[390px] rounded-t-[220px] border border-espresso bg-[#e5ddd1] p-5"><div className="flex h-full flex-col justify-between rounded-t-[200px] bg-espresso p-7 text-cream"><Pill kind="good">Nexora insight</Pill><div><p className="font-display text-5xl tracking-[-.08em]">Не<br/>наугад.</p><p className="mt-4 max-w-[210px] text-xs leading-5 text-[#d9cec0]">Выбираем путь, который выдержит проверку университета.</p></div><span className="text-right text-2xl">✦</span></div></div><div className="absolute bottom-12 left-[-1px] border-y border-r line bg-cream px-7 py-5"><b className="font-display text-4xl tracking-[-.08em]">€4.2M</b><p className="mt-1 text-[10px] font-bold uppercase tracking-[.1em]">грантов привлечено</p></div></div></div></section>
  <section className="mx-auto grid max-w-[1400px] grid-cols-1 border-x line md:grid-cols-3"><Stat n="312" t="поданных кейсов"/><Stat n="94%" t="успешных зачислений"/><Stat n="18" t="университетов-партнёров"/></section>
  <section id="методика-аудита" className="mx-auto max-w-[1400px] px-5 py-25 lg:px-10"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr]"><div><Pill>Методика аудита</Pill><h2 className="mt-5 font-display text-5xl leading-[.95] tracking-[-.06em] lg:text-7xl">Три проверки.<br/><em className="font-normal text-[#b6654e]">Один верный ход.</em></h2></div><p className="max-w-md self-end text-[15px] leading-7 text-taupe">Поступление — это не подбор красивых вузов. Мы последовательно ищем точки риска до того, как они станут причиной отказа.</p></div><div className="mt-14 grid gap-px overflow-hidden border line bg-[#2A211D20] md:grid-cols-3">{[["01","Академическое соответствие","Проверяем аттестаты, кредиты, языковые секции и обязательные предметы."],["02","Финансовый и календарный аудит","Считаем полную стоимость, фактчеким стипендии и разделяем дедлайны грантов и коммерции."],["03","Документы и скрытые условия","Контролируем пакет, страновые требования и условия, спрятанные в правилах приёма."]].map(([n,h,p])=><article className="card min-h-[300px] bg-cream p-7" key={n}><span className="font-display text-4xl text-[#b6654e]">{n}</span><h3 className="mt-15 text-[17px] font-bold tracking-[-.03em]">{h}</h3><p className="mt-3 text-sm leading-6 text-taupe">{p}</p></article>)}</div></section>
  <section id="database" className="bg-espresso px-5 py-23 text-cream lg:px-10"><div className="mx-auto max-w-[1400px]"><div className="flex flex-col justify-between gap-7 md:flex-row md:items-end"><div><Pill kind="good">Интерактивная база вузов</Pill><h2 className="mt-5 font-display text-5xl tracking-[-.06em] lg:text-7xl">Не список. <em className="text-[#dcc6ad]">Карта решений.</em></h2></div><div className="flex rounded-full border border-white/20 p-1 text-xs"><button onClick={()=>setCountry("AT")} className={`rounded-full px-4 py-2 ${country==="AT"?"bg-cream text-espresso":""}`}>🇦🇹 Австрия</button><button onClick={()=>setCountry("HU")} className={`rounded-full px-4 py-2 ${country==="HU"?"bg-cream text-espresso":""}`}>🇭🇺 Венгрия</button></div></div><div className="mt-12 flex items-center justify-between border-y border-white/15 py-4"><span className="text-[11px] uppercase tracking-[.12em] text-[#cdbfb0]">{country==="AT"?"Австрийские университеты":"Венгерские университеты"}</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск специальности или города" className="w-[240px] bg-transparent text-right text-xs outline-none placeholder:text-[#cdbfb0]"/></div><div className="grid gap-px bg-white/15 md:grid-cols-3">{filtered.map(x=><article className="card bg-espresso p-6" key={x.name}><div className="flex justify-between gap-4"><Pill kind={x.tag?"good":"base"}>{x.tag||x.rank}</Pill><span className="text-[11px] text-[#cdbfb0]">{x.city}</span></div><h3 className="mt-14 font-display text-3xl tracking-[-.05em]">{x.name}</h3><p className="mt-2 min-h-10 text-xs leading-5 text-[#cdbfb0]">{x.specialty}</p><div className="mt-8 grid grid-cols-2 gap-y-5 border-t border-white/15 pt-5 text-[11px]"><div><small className="block text-[#cdbfb0]">Обучение</small>{x.fee}</div><div><small className="block text-[#cdbfb0]">Подача</small>{x.apply}</div><div className="col-span-2"><small className="block text-[#cdbfb0]">Грант</small>{x.grant}</div></div></article>)}</div></div></section>
  <section id="кейсы" className="mx-auto max-w-[1400px] px-5 py-25 lg:px-10"><div className="flex flex-col justify-between gap-8 md:flex-row md:items-end"><div><Pill kind="warm">Дедлайны — не фон</Pill><h2 className="mt-5 font-display text-5xl tracking-[-.06em] lg:text-7xl">Ваше время<br/><em className="font-normal text-[#b6654e]">работает на вас.</em></h2></div><p className="max-w-sm text-sm leading-6 text-taupe">Сначала фиксируем окна, которые нельзя упустить. Затем собираем маршрут под конкретную программу.</p></div><div className="mt-14 overflow-x-auto border-y line"><div className="min-w-[760px] divide-y line"><Deadline country="Австрия" color="bg-pistachio" rows={[["Октябрь — январь","Подготовка грантовых заявок","OeAD, Mobility"],["Апрель — сентябрь","Подача на коммерческие программы","осенний набор"]]}/><Deadline country="Венгрия" color="bg-terracotta" rows={[["Ноябрь — январь","Stipendium Hungaricum","бесплатное обучение + стипендия"],["Февраль — июнь","Подача на коммерческие программы","осенний набор"]]}/></div></div></section>
  <section id="pricing" className="bg-sand px-5 py-25 lg:px-10"><div className="mx-auto max-w-[1400px]"><Pill>Стоимость</Pill><h2 className="mt-5 max-w-3xl font-display text-5xl tracking-[-.06em] lg:text-7xl">Прозрачно<br/><em className="font-normal text-[#b6654e]">на каждом этапе.</em></h2><div className="mt-14 grid gap-4 lg:grid-cols-3"><Price name="Аудит кейса" price="€190" text="Экспертный разбор профиля, документов и реальных возможностей." points={["60 минут с экспертом","Оценка соответствия","План на 90 дней"]}/><Price name="Стратегия" price="€690" text="Подбор программ и построение безошибочного маршрута поступления." points={["До 6 программ","Календарь дедлайнов","Финансовый расчёт"]}/><Price featured name="Под ключ" price="от €1 490" text="Полное сопровождение до зачисления и подготовки к переезду." points={["Все документы","Грантовые заявки","Визовая стратегия"]}/></div></div></section>
  <section id="diagnostic" className="mx-auto max-w-[1400px] px-5 py-25 lg:px-10"><div className="grid overflow-hidden rounded-sm bg-espresso text-cream lg:grid-cols-2"><div className="p-8 lg:p-14"><Pill kind="good">Первая диагностика — бесплатно</Pill><h2 className="mt-6 font-display text-5xl tracking-[-.06em] lg:text-6xl">Разберёмся, <em className="text-[#dcc6ad]">что возможно</em> именно для вас.</h2><p className="mt-6 max-w-md text-sm leading-6 text-[#cdbfb0]">30 минут, чтобы увидеть реальные варианты поступления, риски и ближайшие дедлайны.</p></div><form onSubmit={e=>{e.preventDefault();setSent(true)}} className="flex flex-col justify-center bg-[#3a2e28] p-8 lg:p-14"><input required placeholder="Ваше имя" className="border-b border-white/30 bg-transparent py-4 text-sm outline-none placeholder:text-[#cdbfb0]"/><input required type="email" placeholder="Email или Telegram" className="border-b border-white/30 bg-transparent py-4 text-sm outline-none placeholder:text-[#cdbfb0]"/><button className="mt-8 rounded-full bg-pistachio px-5 py-4 text-xs font-bold text-espresso">{sent?"Заявка принята ✓":"Записаться на диагностику ↗"}</button><p className="mt-3 text-[10px] leading-4 text-[#cdbfb0]">Отправляя форму, вы соглашаетесь на обработку данных.</p></form></div></section>
  <footer className="border-t line px-5 py-10 lg:px-10"><div className="mx-auto flex max-w-[1400px] flex-col justify-between gap-8 text-xs md:flex-row"><div><a className="font-display text-2xl">Nexora Admissions</a><p className="mt-3 max-w-xs leading-5 text-taupe">Информация о правилах приёма актуальна для 2026/2027 учебного года и уточняется перед подачей.</p></div><div className="flex gap-8"><a href="https://instagram.com/nexora.admissions">Instagram ↗<br/><b>@nexora.admissions</b></a><a href="https://t.me/nexora_support">Telegram ↗<br/><b>@nexora_support</b></a></div><span>© 2026 Nexora Admissions</span></div></footer>
</main>}
function Stat({n,t}:{n:string;t:string}){return <div className="border-b line px-6 py-8 text-center last:border-0 md:border-b-0 md:border-r"><b className="font-display text-5xl tracking-[-.07em]">{n}</b><p className="mt-2 text-[10px] font-bold uppercase tracking-[.12em] text-taupe">{t}</p></div>}
function Deadline({country,color,rows}:{country:string;color:string;rows:string[][]}){return <div className="grid grid-cols-[150px_1fr_1fr] gap-5 py-6 text-xs"><b>{country}</b>{rows.map(([date,name,note])=><div key={name}><Pill kind={color==="bg-pistachio"?"good":"warm"}>{date}</Pill><p className="mt-3 font-bold">{name}</p><small className="text-taupe">{note}</small></div>)}</div>}
function Price({name,price,text,points,featured}:{name:string;price:string;text:string;points:string[];featured?:boolean}){return <article className={`card border p-7 ${featured?"border-espresso bg-espresso text-cream":"line bg-cream"}`}><Pill kind={featured?"good":"base"}>{featured?"Самый полный":"Поступление без иллюзий"}</Pill><h3 className="mt-12 text-lg font-bold">{name}</h3><b className="mt-3 block font-display text-5xl tracking-[-.07em]">{price}</b><p className={`mt-4 min-h-12 text-sm leading-6 ${featured?"text-[#cdbfb0]":"text-taupe"}`}>{text}</p><ul className={`mt-7 space-y-3 border-t pt-5 text-xs ${featured?"border-white/15":"line"}`}>{points.map(x=><li key={x}>✦ <span className="ml-2">{x}</span></li>)}</ul><a href="#diagnostic" className={`mt-8 block rounded-full px-4 py-3 text-center text-xs font-bold ${featured?"bg-pistachio text-espresso":"border line"}`}>Выбрать пакет</a></article>}
